<?php declare(strict_types=1);require __DIR__.'/app/admin.php';$user=require_nonagon_admin();$id=investment_text($_GET,'id',36);$op=investment_opportunity($user,$id);$technical=rows('SELECT * FROM investment_technical_profiles WHERE opportunity_id=?',[$id])[0]??[];$acquisition=rows('SELECT * FROM investment_acquisition_profiles WHERE opportunity_id=?',[$id])[0]??[];$scenarios=rows('SELECT * FROM investment_financial_scenarios WHERE opportunity_id=?',[$id]);$reviews=rows('SELECT r.*,u.full_name reviewer_name FROM investment_due_diligence_reviews r LEFT JOIN users u ON u.id=r.reviewer_id WHERE r.opportunity_id=?',[$id]);$reviewMap=[];foreach($reviews as $review)$reviewMap[$review['review_area']]=$review;$issues=investment_publish_issues($id);$adminView='investment';$pageTitle='Review opportunity';require __DIR__.'/includes/admin-header.php';?>
<header class="admin-heading"><div><p><?= e($op['organization_name']) ?></p><h1><?= e($op['title']) ?></h1><p><?= e($op['opportunity_rationale']) ?></p></div><a class="admin-button" href="admin?view=investment">Back to queue</a></header><section class="admin-panel"><h2>Opportunity summary</h2><div class="admin-grid"><div><strong>Equipment</strong><p><?= e($technical['oem_name']??'') ?> <?= e($technical['model_name']??'') ?></p><small><?= nl2br(e($technical['specification']??'')) ?></small></div><div><strong>Acquisition</strong><p><?= e($acquisition['supplier_name']??'Not supplied') ?></p><small>Landed cost <?= e($op['currency']) ?> <?= number_format((float)($acquisition['landed_cost']??0),2) ?></small></div><div><strong>Ownership and security</strong><p><?= e($op['ownership_vehicle']) ?></p><small><?= e($op['finance_security_partner']) ?></small></div><div><strong>Risk</strong><p><?= e($op['primary_risks']) ?></p></div></div><?php if($issues):?><h3>Publication blockers</h3><ul><?php foreach($issues as $issue):?><li><?= e($issue) ?></li><?php endforeach;?></ul><?php endif;?></section><section class="admin-panel"><h2>Human review areas</h2><div class="admin-review-grid"><?php foreach(INVESTMENT_REVIEW_AREAS as $area):$review=$reviewMap[$area]??[];?><article><h3><?= e(str_replace('_',' ',$area)) ?></h3><p><span class="admin-badge <?= strtolower($review['status']??'') ?>"><?= e($review['status']??'NOT STARTED') ?></span></p><small><?= e($review['findings']??'No findings recorded.') ?></small><form action="admin-action" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="opportunity_review"><input type="hidden" name="id" value="<?= e($id) ?>"><input type="hidden" name="review_area" value="<?= e($area) ?>"><select name="status"><option>IN_REVIEW</option><option>APPROVED</option><option>CONDITIONAL</option><option>REJECTED</option></select><textarea name="findings" placeholder="Findings"><?= e($review['findings']??'') ?></textarea><textarea name="conditions" placeholder="Conditions"><?= e($review['conditions']??'') ?></textarea><textarea name="blockers" placeholder="Blockers"><?= e($review['blockers']??'') ?></textarea><button>Record review</button></form></article><?php endforeach;?></div></section><section class="admin-panel"><h2>Workflow decision</h2><p>Current status: <span class="admin-badge <?= strtolower($op['status']) ?>"><?= e($op['status']) ?></span></p><div class="admin-actions"><?php $transitions=['SUBMITTED'=>['DUE_DILIGENCE','REJECTED'],'DUE_DILIGENCE'=>['REVIEW'],'REVIEW'=>['APPROVED','CONDITIONAL','REJECTED'],'APPROVED'=>['PUBLISHED'],'PUBLISHED'=>['WITHDRAWN']];foreach($transitions[$op['status']]??[] as $to):?><form action="admin-action" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="opportunity_transition"><input type="hidden" name="id" value="<?= e($id) ?>"><button name="to_status" value="<?= e($to) ?>"><?= e(str_replace('_',' ',$to)) ?></button></form><?php endforeach;?></div></section><?php require __DIR__.'/includes/admin-footer.php';?>
